// Des: Unit tests for chain runs, rings, abort, watchdog
// Flo: build Sche without threads > feed fixed beats > assert chain steps
// I/O: Task specs + fake clock ms > pass or fail
// ===================================================================
const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("taskarm"); const supe = @import("tasksuper"); const tick = @import("tk-task-tick.zig");
const tszz = std.testing; const Sche = tick.Sche; const CF = tick.CF;
fn plusJson(allo: std.mem.Allocator, json: []const u8) std.json.Value { return std.json.parseFromSliceLeaky(std.json.Value, allo, json, .{}) catch unreachable; }
test "chainTick: members run in order, plus waits between them, off skipped, a failure does not stop it" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const plus_secs = plusJson(aren.allocator(), "[\"y\",\"m\",\"d\",\"h\",\"n\",[1]]"); var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.prng = std.Random.DefaultPrng.init(1); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x" }, .{ .id = "off", .type = "hand", .run = "x", .on = false }, .{ .id = "b", .type = "hand", .run = "x" }, .{ .id = "c", .type = "hand", .run = "x" }, .{ .id = "ch", .type = "chai", .plus = plus_secs, .ids = &.{ "a", "off", "b", "c" } } }; var arme = [_]armz.Armed{try armz.armTask(list[4])}; sche.arme = &arme; var duez: [8]Sche.Jobz = undefined; var coun: usize = 0; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var fini_coun: usize = 0; const none = [_]supe.Done{}; const idlz = list[0..]; const nowz = time.localNow(); sche.chaiTick(iozz, nowz, 1_000, &none, idlz, &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); try tszz.expectEqualStrings("a", duez[0].iden); coun = 0; sche.chaiTick(iozz, nowz, 3_000, &none, idlz, &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), coun); var ring: supe.DoneRing = .{}; ring.push("a", true, 0); sche.chaiTick(iozz, nowz, 4_000, ring.item(), idlz, &duez, &coun, &fini, &fini_coun); sche.chaiTick(iozz, nowz, 4_999, &none, idlz, &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), coun); sche.chaiTick(iozz, nowz, 5_000, &none, idlz, &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); try tszz.expectEqualStrings("b", duez[0].iden); coun = 0; ring.clea(); ring.push("b", false, 0); sche.chaiTick(iozz, nowz, 6_000, ring.item(), idlz, &duez, &coun, &fini, &fini_coun); sche.chaiTick(iozz, nowz, 7_000, &none, idlz, &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); try tszz.expectEqualStrings("c", duez[0].iden); coun = 0; ring.clea(); ring.push("c", true, 0); sche.chaiTick(iozz, nowz, 8_000, ring.item(), idlz, &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), fini_coun); try tszz.expectEqual(@as(u32, 3), fini[0].ranz); try tszz.expectEqual(@as(u32, 1), fini[0].fail); try tszz.expectEqualStrings("b", fini[0].fail_buff[0..fini[0].fail_leng]); try tszz.expectEqual(@as(usize, 1), sche.done.leng); try tszz.expect(!sche.done.bufz[0].okzz); sche.chaiTick(iozz, nowz, 9_000, &none, idlz, &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), coun); try tszz.expect(arme[0].requestHand()); sche.chaiTick(iozz, nowz, 10_000, &none, idlz, &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); try tszz.expectEqualStrings("a", duez[0].iden); }
test "chainTick: a member that skipped on purpose (exit 4) starts the next step without the plus wait" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const plus_secs = plusJson(aren.allocator(), "[\"y\",\"m\",\"d\",\"h\",\"n\",[1]]"); var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.prng = std.Random.DefaultPrng.init(1); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x" }, .{ .id = "b", .type = "hand", .run = "x" }, .{ .id = "ch", .type = "chai", .plus = plus_secs, .ids = &.{ "a", "b" } } }; var arme = [_]armz.Armed{try armz.armTask(list[2])}; sche.arme = &arme; var duez: [8]Sche.Jobz = undefined; var coun: usize = 0; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var fini_coun: usize = 0; const none = [_]supe.Done{}; const nowz = time.localNow(); sche.chaiTick(iozz, nowz, 1_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqualStrings("a", duez[0].iden); coun = 0; var ring: supe.DoneRing = .{}; ring.skipPush("a", true, 0, true); sche.chaiTick(iozz, nowz, 4_000, ring.item(), list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); try tszz.expectEqualStrings("b", duez[0].iden); }
test "chainTick: dela delays the first step after an automatic start; a manual fire skips it" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x" }, .{ .id = "ch", .type = "chai", .sche = "boot", .dela = 2, .ids = &.{"a"} } }; const none = [_]supe.Done{}; const nowz = time.localNow(); var duez: [4]Sche.Jobz = undefined; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; for ([_]bool{ false, true }) |hand| { var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.prng = std.Random.DefaultPrng.init(1); var arme = [_]armz.Armed{try armz.armTask(list[1])}; sche.arme = &arme; var coun: usize = 0; var fini_coun: usize = 0; if (hand) _ = arme[0].requestHand(); sche.chaiTick(iozz, nowz, 1_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); if (hand) { try tszz.expectEqual(@as(usize, 1), coun); } else { try tszz.expectEqual(@as(usize, 0), coun); sche.chaiTick(iozz, nowz, 120_999, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), coun); sche.chaiTick(iozz, nowz, 121_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); } } }
test "chain step rings: one per step, listed as <chain>~<n>, attachable, sealed with the exit event" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x" }, .{ .id = "ch", .type = "chai", .sche = "boot", .ids = &.{"a"} } }; const none = [_]supe.Done{}; var duez: [4]Sche.Jobz = undefined; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.root = "E:\\hub"; sche.chai_ring = true; sche.prng = std.Random.DefaultPrng.init(1); var arme = [_]armz.Armed{try armz.armTask(list[1])}; sche.arme = &arme; var coun: usize = 0; var fini_coun: usize = 0; sche.chaiTick(iozz, time.localNow(), 1_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); const ring = duez[0].teez.?; defer Sche.ringDrop(&sche.chai[0]); defer ring.rele(); try tszz.expect(sche.chaiRing(iozz, "ch~2") == null and sche.chaiRing(iozz, "ch") == null and sche.chaiRing(iozz, "nope~1") == null); const gotz = sche.chaiRing(iozz, "ch~1").?; gotz.rele(); var outz: std.Io.Writer.Allocating = .init(tszz.allocator); defer outz.deinit(); try sche.chaiJobzWrit(iozz, &outz.writer, false); try tszz.expect(std.mem.indexOf(u8, outz.writer.buffered(), "\"id\":\"ch~1\",\"cmd\":\"a\"") != null); try tszz.expect(std.mem.indexOf(u8, outz.writer.buffered(), "\"done\":false") != null); Sche.ringSeal(iozz, ring, 3, 1200); var buff: [512]u8 = undefined; const read = ring.fromRead(iozz, 0, &buff); try tszz.expect(read.done and std.mem.indexOf(u8, buff[0..read.byte], "\"t\":\"exit\",\"code\":3") != null); }
test "chain abort: ends a running chain at once, logs it as aborted, leaves no stale mark" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x" }, .{ .id = "b", .type = "hand", .run = "x" }, .{ .id = "ch", .type = "chai", .sche = "boot", .ids = &.{ "a", "b" } } }; const none = [_]supe.Done{}; const nowz = time.localNow(); var duez: [4]Sche.Jobz = undefined; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.prng = std.Random.DefaultPrng.init(1); var arme = [_]armz.Armed{try armz.armTask(list[2])}; sche.arme = &arme; var coun: usize = 0; var fini_coun: usize = 0; try tszz.expect(!sche.chaiAbor(iozz, "ch")); sche.chaiTick(iozz, nowz, 1_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); const view = sche.chaiView(iozz, "ch").?; try tszz.expect(!view.wait and view.indx == 0); try tszz.expect(sche.chaiAbor(iozz, "ch")); try tszz.expectEqual(@as(usize, 0), sche.abor_leng); sche.chaiTick(iozz, nowz, 2_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), fini_coun); try tszz.expect(fini[0].abor); try tszz.expect(sche.chaiView(iozz, "ch") == null); try tszz.expectEqual(@as(usize, 1), coun); }
test "chainTick: a clock trigger starts it, a trigger while running is ignored, a saved wait resumes" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.prng = std.Random.DefaultPrng.init(1); var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const zero = plusJson(aren.allocator(), "[[0],[0],[0],[0],[0],[0]]"); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x" }, .{ .id = "ch", .type = "chai", .sche = "5s", .plus = zero, .ids = &.{"a"} } }; var arme = [_]armz.Armed{try armz.armTask(list[1])}; sche.arme = &arme; var duez: [4]Sche.Jobz = undefined; var coun: usize = 0; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var fini_coun: usize = 0; const none = [_]supe.Done{}; const nowz = time.localNow(); sche.chaiTick(iozz, nowz, 1_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); sche.chaiTick(iozz, nowz, 5_999, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), coun); sche.chaiTick(iozz, nowz, 6_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); coun = 0; sche.chaiTick(iozz, nowz, 11_000, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), coun); var chai: Sche.ChaiRunz = .{}; Sche.chaiResu(&chai, .{ .inde = 2, .ranz = 2, .fail = 1, .next_msec = 5_000, .star_msec = 1_000 }); try tszz.expect(chai.runn and chai.wait and chai.boot); try tszz.expectEqual(@as(usize, 2), chai.indx); try tszz.expectEqual(@as(u32, 1), chai.fail); }
test "chainTick: an id with no job line runs the cmds script with the chain's settings; a real line wins" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const zero = plusJson(aren.allocator(), "[[0],[0],[0],[0],[0],[0]]"); var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.root = "E:\\hub"; sche.prng = std.Random.DefaultPrng.init(1); const list = [_]stor.Task{ .{ .id = "real", .type = "hand", .run = "echo x", .tmo = 10 }, .{ .id = "ch", .type = "chai", .plus = zero, .@"try" = 2, .tmo = 300, .lock = "sync", .ids = &.{ "virt", "real" } } }; var arme = [_]armz.Armed{try armz.armTask(list[1])}; sche.arme = &arme; var duez: [4]Sche.Jobz = undefined; var coun: usize = 0; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var fini_coun: usize = 0; const none = [_]supe.Done{}; const nowz = time.localNow(); sche.chaiTick(iozz, nowz, 0, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); try tszz.expectEqualStrings("virt", duez[0].iden); try tszz.expect(std.mem.indexOf(u8, duez[0].runz, "-cmds-") != null); try tszz.expect(std.mem.endsWith(u8, duez[0].runz, " virt")); try tszz.expectEqual(@as(u32, 2), duez[0].retr); try tszz.expectEqual(@as(u32, 300_000), duez[0].time_msec); try tszz.expectEqualStrings("sync", duez[0].lock); coun = 0; var ring: supe.DoneRing = .{}; ring.push("virt", true, 0); sche.chaiTick(iozz, nowz, 1_000, ring.item(), list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); try tszz.expectEqualStrings("real", duez[0].iden); try tszz.expectEqualStrings("echo x", duez[0].runz); try tszz.expectEqual(@as(u32, 0), duez[0].retr); try tszz.expectEqual(@as(u32, 10_000), duez[0].time_msec); }
test "chainTick: a member that never reports is given up on (watchdog)" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.prng = std.Random.DefaultPrng.init(1); var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const zero = plusJson(aren.allocator(), "[[0],[0],[0],[0],[0],[0]]"); const list = [_]stor.Task{ .{ .id = "a", .type = "hand", .run = "x", .tmo = 10 }, .{ .id = "ch", .type = "chai", .plus = zero, .ids = &.{"a"} } }; var arme = [_]armz.Armed{try armz.armTask(list[1])}; sche.arme = &arme; var duez: [4]Sche.Jobz = undefined; var coun: usize = 0; var fini: [CF.chai_fini_maxz]Sche.ChaiFini = undefined; var fini_coun: usize = 0; const none = [_]supe.Done{}; const nowz = time.localNow(); sche.chaiTick(iozz, nowz, 0, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), coun); sche.chaiTick(iozz, nowz, CF.chai_slac_msec, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 0), fini_coun); sche.chaiTick(iozz, nowz, 10_000 + CF.chai_slac_msec, &none, list[0..], &duez, &coun, &fini, &fini_coun); try tszz.expectEqual(@as(usize, 1), fini_coun); try tszz.expectEqual(@as(u32, 1), fini[0].fail); }
